#include <list>
#include <algorithm>

int main() {
    std::list<int> coll = {1, 4, 2, 4, 3, 4, 5};

    // Efficient removal using member function (O(N) pointer manipulation)
    coll.remove(4); 

    // Inefficient way (requires two steps, would shift elements in vector)
    // auto new_end = std::remove(coll.begin(), coll.end(), 4);
    // coll.erase(new_end, coll.end()); 

    // Use remove_if
    coll.remove_if([](int x){ return x % 2 == 0; });
    // coll now contains {1, 3, 5}
}
